import * as React from "react";
import { Box } from "@mui/material";
import { useSwipeable } from "react-swipeable";
import { motion, AnimatePresence } from "framer-motion";
import NavigationBar from "./NavigationBar";
import HomePage from "./HomePage";
import VenuesPage from "./VenuesPage";
import HairPage from "./HairPage";
import MakeupPage from "./MakeupPage";
import PhotographersPage from "./PhotographersPage";
import MusicPage from "./MusicPage";
import FloristPage from "./FloristPage";
import DresserPage from "./DresserPage";
import PlannerPage from "./PlannerPage";

export default function NewPage() {
  const [activePage, setActivePage] = React.useState(0);
  const [direction, setDirection] = React.useState(1); // 1 for next, -1 for previous

  const pages = [
    <HomePage key="home" />,
    <VenuesPage key="venues" />,
    <HairPage key="hair" />,
    <MakeupPage key="makeup" />,
    <PhotographersPage key="photographers" />,
    <MusicPage key="music" />,
    <FloristPage key="florist" />,
    <DresserPage key="dresser" />,
    <PlannerPage key="planner" />,
  ];

  const handlePageChange = (page: string) => {
    const pageIndex = {
      home: 0,
      venues: 1,
      hair: 2,
      makeup: 3,
      photographers: 4,
      music: 5,
      florist: 6,
      dresser: 7,
      planner: 8,
    }[page];

    if (pageIndex !== undefined) {
      setDirection(pageIndex > activePage ? 1 : -1);
      setActivePage(pageIndex);
    }
  };

  const handlers = useSwipeable({
    onSwipedLeft: () => {
      if (activePage < pages.length - 1) {
        setDirection(1);
        setActivePage(activePage + 1);
      }
    },
    onSwipedRight: () => {
      if (activePage > 0) {
        setDirection(-1);
        setActivePage(activePage - 1);
      }
    },
    trackMouse: true,
  });

  return (
    <>
      <NavigationBar onSelect={handlePageChange} activePage={activePage} />
      <Box
        {...handlers}
        sx={{
          padding: 4,
          paddingBottom: "60px",
          paddingTop: "80px",
          minHeight: "calc(100vh - 60px)",
          overflow: "hidden",
          position: "relative",
        }}
      >
        <AnimatePresence custom={direction} mode="wait">
          <motion.div
            key={activePage}
            initial={{ x: direction === 1 ? "100%" : "-100%", opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: direction === 1 ? "-100%" : "100%", opacity: 0 }}
            transition={{ duration: 0.4, ease: "easeInOut" }}
            style={{ position: "absolute", width: "100%" }}
          >
            {pages[activePage]}
          </motion.div>
        </AnimatePresence>
      </Box>
    </>
  );
}



